-- Business content, written in (owner, 21 Sep 2026: "add content ... do it"), and a studio can only
-- belong to a business profile ("a studio is a type of business profile").
--
-- 1. Opening hours for the 24 business accounts that had none, typical for each kind: studios get
--    real weekly_hours (so their booking calendar works) and the matching line on the studio and
--    the business profile; labels, agencies, schools, venues and rental businesses get the line.
-- 2. Bios for the 4 businesses with none (Beatcraft Studios, Krimson Avenue, Sound Solutions,
--    Blue Sitar Venues).
-- 3. Beatcraft Studios: city, photo, address and its studio (studio-type business).
-- 4. studios.owner_profile_id must be a profile_business row (ON DELETE CASCADE: removing the
--    business removes its studio). Every studio already had one when this was written.
-- Only empty values are filled; nothing an owner wrote is overwritten.
-- Snapshot: supabase/dumps/2026-09-21-before-business-content.sql
--
-- Rollback:
--   ALTER TABLE public.studios DROP CONSTRAINT IF EXISTS studios_owner_business_fkey;
--   DELETE FROM public.studios WHERE slug = 'beatcraft-studios';
--   then set the fields listed in the snapshot back to null / {}.

BEGIN;
UPDATE public.profiles SET city='Mumbai', state='Maharashtra', country='India', avatar_url=coalesce(avatar_url,'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?auto=format&fit=crop&w=800&q=80') WHERE username='beatcraft.studios';
UPDATE public.profile_business SET business_address=coalesce(business_address,'Andheri West, Mumbai'), logo_url=coalesce(logo_url,'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?auto=format&fit=crop&w=800&q=80') WHERE profile_id=(SELECT id FROM public.profiles WHERE username='beatcraft.studios');
INSERT INTO public.studios (owner_profile_id, slug, name, description, location, image_url, images, services)
SELECT id, 'beatcraft-studios', 'Beatcraft Studios', 'Beat production studio for trap, lo-fi and hip-hop. Exclusive and lease licences on instrumentals, custom beats made to brief, and vocal recording sessions.', 'Andheri West, Mumbai', 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?auto=format&fit=crop&w=800&q=80', ARRAY['https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?auto=format&fit=crop&w=800&q=80'], ARRAY['recording','mixing']
FROM public.profiles WHERE username='beatcraft.studios' AND NOT EXISTS (SELECT 1 FROM public.studios s WHERE s.owner_profile_id=profiles.id);
UPDATE public.profiles SET bio='Beat production studio for trap, lo-fi and hip-hop. Exclusive and lease licences on instrumentals, custom beats made to brief, and vocal recording sessions.' WHERE username='beatcraft.studios' AND coalesce(bio,'')='';
