UPDATE public.profiles SET bio='Live music venue for concerts, private events and showcases, with in-house sound and backline available for hire.' WHERE username='blue.sitar.venues' AND coalesce(bio,'')='';
UPDATE public.studios SET weekly_hours='{"mon": [{"open": "10:00", "close": "20:00"}], "tue": [{"open": "10:00", "close": "20:00"}], "wed": [{"open": "10:00", "close": "20:00"}], "thu": [{"open": "10:00", "close": "20:00"}], "fri": [{"open": "10:00", "close": "20:00"}], "sat": [{"open": "10:00", "close": "20:00"}]}'::jsonb, operating_hours='Mon–Sat 10:00–20:00 · Sun closed' WHERE owner_profile_id=(SELECT id FROM public.profiles WHERE username='analog.ensemble.studios') AND (weekly_hours IS NULL OR weekly_hours='{}'::jsonb);
